function R:Get(mapID, spellID)
    mapID = tonumber(mapID)
    spellID = tonumber(spellID)
    if not mapID or not spellID then return nil end
    local m = self.maps[mapID]
    return m and m[spellID] or nil
end

function R:GetStatus()
    return self.meta
end
